// U1 Gemini Error Handler — strict envelope entry guard. Hard-fail on contract violation.
const input = $input.first().json;
const e164 = /^\+?[1-9]\d{6,14}$/;
if (typeof input.phoneNumber !== 'string' || !e164.test(input.phoneNumber)) {
  throw new Error('U1 entry-guard: phoneNumber missing or not E.164: ' + JSON.stringify(input.phoneNumber));
}
if (typeof input.userFacing !== 'boolean') {
  throw new Error('U1 entry-guard: userFacing missing or not boolean: ' + JSON.stringify(input.userFacing));
}
if (input.context === null || typeof input.context !== 'object' || Array.isArray(input.context)) {
  throw new Error('U1 entry-guard: context missing or not an object');
}
const cid = input.consultChannelId;
if (cid !== undefined && cid !== null && cid !== '' && !/^[CDG][A-Z0-9]+$/.test(cid)) {
  throw new Error('U1 entry-guard: consultChannelId not a valid Slack channel id: ' + JSON.stringify(cid));
}
return [{ json: {
  phoneNumber: input.phoneNumber,
  userFacing: input.userFacing,
  consultChannelId: (cid === undefined || cid === '' ? null : cid),
  context: input.context
} }];

// U1 — assemble the admin alert text from the structured context; resolve the alert channel.
// channelId defaults to the admin-commands channel when no consult channel was supplied.
const env = $('Entry Guard').item.json;
const ctx = env.context || {};
const ADMIN_CMDS = 'C0A5B0ZE81E';
const channelId = env.consultChannelId || ADMIN_CMDS;

const clip = (s, n) => {
  if (s === undefined || s === null || s === '') return '\u2014';
  const str = String(s);
  return str.length > n ? str.slice(0, n) + '\u2026' : str;
};

const userName = clip(ctx.userName, 100);
const userState = clip(ctx.userStateText, 100);
const userMessage = clip(ctx.userMessage, 500);
const errorDetail = clip(ctx.errorDetail, 200);

const messageText =
  '\u26a0\ufe0f The AI assistant couldn\u2019t generate a reply to a user just now.\n\n' +
  '*User:* ' + userName + ' (' + env.phoneNumber + ')\n' +
  '*Their state:* ' + userState + '\n' +
  '*Their question:* "' + userMessage + '"\n' +
  '*Reason:* ' + errorDetail + '\n\n' +
  'The user has been told there\u2019s a technical hiccup and that the team will follow up. ' +
  'Suggested action: respond manually in their consult channel.';

return [{ json: { channelId, messageText } }];

